# frozen_string_literal: true

def family_planner_markup
  today = Date.today.iso8601
  %(<section class="organizer-app" data-family-planner>
  <header class="organizer-hero"><div><span class="eyebrow">ĢIMENES NEDĒĻAS PLĀNS</span><h2>Vienā ritmā, katram savs krāsu kods.</h2><p>Pievieno ģimenes locekļus, kopīgus notikumus, darbus un maltīšu idejas. Ieraksti tiek glabāti tikai šajā pārlūkā.</p></div><svg class="icon organizer-hero-icon" aria-hidden="true"><use href="#i-family"/></svg></header>
  <section class="organizer-toolbar"><div><button type="button" data-family-step="-7" aria-label="Iepriekšējā nedēļa">‹</button><button type="button" data-family-today>Šī nedēļa</button><button type="button" data-family-step="7" aria-label="Nākamā nedēļa">›</button><label>Nedēļas datums<input type="date" data-family-date data-riga-today value="#{today}"></label></div><div class="actions"><button type="button" data-family-export>Lejupielādēt JSON</button><label class="button organizer-file-button">Atjaunot dublējumu<input type="file" data-family-import accept="application/json,.json" hidden></label><button type="button" data-family-ics>Eksportēt ICS</button><button type="button" data-family-print>Drukāt nedēļu</button></div></section>
  <section class="organizer-card"><div class="organizer-heading"><div><span class="eyebrow">JŪSU CILVĒKI</span><h2>Ģimenes locekļi</h2></div><span data-family-member-count>0 / 8</span></div><form class="organizer-inline-form" data-family-member-form><label>Vārds<input name="name" maxlength="40" required placeholder="Piem., Līva"></label><label>Krāsa<select name="color"><option value="#8b2940">Dzērvene</option><option value="#32796d">Jūras zaļš</option><option value="#4268a2">Rudzupuķe</option><option value="#bd7b31">Dzintars</option><option value="#795b9c">Vijolīte</option><option value="#687947">Sūna</option><option value="#bb6683">Roze</option><option value="#596a77">Dūmaka</option></select></label><button class="primary" type="submit">Pievienot cilvēku</button></form><div class="organizer-chip-list" data-family-members></div></section>
  <div class="organizer-two-col"><section class="organizer-card"><div class="organizer-heading"><div><span class="eyebrow">KOPĪGIE PLĀNI</span><h2>Pievieno notikumu vai darāmo</h2></div></div><form class="organizer-form" data-family-entry-form><label>Kas jāpaveic?<input name="title" maxlength="120" required></label><div class="organizer-form-grid"><label>Veids<select name="type"><option value="event">Notikums</option><option value="task">Darāmais</option><option value="chore">Mājas darbs</option></select></label><label>Datums<input name="date" type="date" data-riga-today value="#{today}" required></label><label>Sākums<input name="start" type="time"></label><label>Beigas<input name="end" type="time"></label><label>Atbildīgais<select name="member" data-family-member-select><option value="">Kopīgs plāns</option></select></label><label>Atgādinājums ICS failā<select name="reminder"><option value="0">Bez atgādinājuma</option><option value="15">15 minūtes iepriekš</option><option value="30">30 minūtes iepriekš</option><option value="60">1 stundu iepriekš</option></select></label><label>Atkārtošana<select name="repeat"><option value="none">Vienu reizi</option><option value="weekly">Katru nedēļu</option></select></label><label>Atkārtojuma pēdējā diena<input type="date" name="until"></label></div><button class="primary" type="submit">Saglabāt plānā</button></form></section>
  <section class="organizer-card"><div class="organizer-heading"><div><span class="eyebrow">NEDĒĻAS ĒDIENREIZES</span><h2>Maltīšu plāns</h2></div></div><form class="organizer-form" data-family-meal-form><div class="organizer-form-grid"><label>Datums<input name="date" type="date" data-riga-today value="#{today}" required></label><label>Maltīte<input name="title" maxlength="100" required placeholder="Piem., dārzeņu zupa"></label></div><label>Sastāvdaļas, atdalītas ar komatiem<textarea name="ingredients" rows="2" maxlength="500" placeholder="Burkāni, kartupeļi, dilles"></textarea></label><button type="submit">Pievienot ēdienkarti</button></form><div data-family-meals></div><form class="organizer-inline-form shopping-add-form" data-family-shopping-form><label>Pirkumu saraksts<input name="item" maxlength="100" required placeholder="Pievieno produktu"></label><label>Daudzums<input name="amount" maxlength="30" placeholder="Piem., 2 kg"></label><label>Nodaļa<select name="aisle"><option>Pārējais</option><option>Augļi un dārzeņi</option><option>Piena produkti</option><option>Maize</option><option>Saimniecībai</option></select></label><button type="submit">Pievienot</button></form><button type="button" data-shopping-clear-done>Noņemt nopirkto</button><div data-family-shopping></div></section></div>
  <section class="organizer-card organizer-week-card"><div class="organizer-heading"><div><span class="eyebrow">KOPSKATS</span><h2 data-family-week-title></h2></div><span class="organizer-local-note">Tikai šajā ierīcē</span></div><div class="family-week-grid" data-family-week></div></section><p class="organizer-status" data-family-status role="status" aria-live="polite"></p><details class="organizer-privacy"><summary>Glabāšana, atkārtojumi un imports</summary><p>Dati nepamet pārlūku un netiek sinhronizēti starp ierīcēm. Regulārs nedēļas notikums tiek eksportēts kā Europe/Riga atkārtojums. JSON dublējumu saglabā drošā vietā; importēšana aizstāj šī plānotāja vietējos datus. Plāns pats par sevi nenosaka skolas, darba vai veselības ieteikumus.</p></details>
  </section>)
end

def timetable_planner_markup
  today = Date.today.iso8601
  period_end = (Date.today + 120).iso8601
  %(<section class="organizer-app" data-timetable-planner>
  <header class="organizer-hero timetable-hero"><div><span class="eyebrow">MĀCĪBAS · NEDĒĻAS RITMS</span><h2>Stundu saraksts, ko pielāgo pats.</h2><p>Saliec nodarbības un termiņus, pārbaudi pārklāšanos un saglabā mācību plānu šajā pārlūkā.</p></div><svg class="icon organizer-hero-icon" aria-hidden="true"><use href="#i-school"/></svg></header>
  <section class="organizer-toolbar"><div><button type="button" data-class-week-step="-7" aria-label="Iepriekšējā nedēļa">‹</button><button type="button" data-class-today>Šī nedēļa</button><button type="button" data-class-week-step="7" aria-label="Nākamā nedēļa">›</button><label>Nedēļas datums<input type="date" data-class-date data-riga-today value="#{today}"></label></div><div class="actions"><button type="button" data-class-export>Lejupielādēt JSON</button><label class="button organizer-file-button">Atjaunot dublējumu<input type="file" data-class-import accept="application/json,.json" hidden></label><label>ICS tvērums<select data-class-ics-scope><option value="week">Izvēlētā nedēļa</option><option value="period">Viss mācību periods</option></select></label><button type="button" data-class-ics>Eksportēt ICS</button><button type="button" data-class-print>Drukāt nedēļu</button></div></section>
  <div class="organizer-two-col"><section class="organizer-card"><div class="organizer-heading"><div><span class="eyebrow">NODARBĪBAS</span><h2>Pievieno stundu</h2></div></div><form class="organizer-form" data-class-lesson-form><input type="hidden" name="id"><label>Mācību priekšmets<input name="subject" maxlength="90" required placeholder="Piem., Matemātika"></label><div class="organizer-form-grid"><label>Nedēļas diena<select name="weekday"><option value="1">Pirmdiena</option><option value="2">Otrdiena</option><option value="3">Trešdiena</option><option value="4">Ceturtdiena</option><option value="5">Piektdiena</option><option value="6">Sestdiena</option><option value="0">Svētdiena</option></select></label><label>Sākums<input name="start" type="time" value="08:00" required></label><label>Beigas<input name="end" type="time" value="08:45" required></label><label>Telpa<input name="room" maxlength="60"></label><label>Skolotājs<input name="teacher" maxlength="80"></label><label>Krāsa<select name="color"><option value="#8b2940">Dzērvene</option><option value="#32796d">Jūras zaļš</option><option value="#4268a2">Rudzupuķe</option><option value="#bd7b31">Dzintars</option><option value="#795b9c">Vijolīte</option><option value="#687947">Sūna</option></select></label><label>Periods no<input name="from" type="date" data-riga-today value="#{today}" required></label><label>Līdz<input name="until" type="date" value="#{period_end}" required></label></div><button class="primary" type="submit" data-class-submit>Pievienot stundu</button><button type="button" data-class-cancel hidden>Atcelt labojumu</button></form><p class="organizer-hint">Atkārtojums darbojas norādītajā periodā; skolas brīvlaiku plāns netiek izslēgts automātiski.</p></section>
  <section class="organizer-card"><div class="organizer-heading"><div><span class="eyebrow">UZDEVUMI UN PĀRBAUDES</span><h2>Mācību termiņi</h2></div></div><form class="organizer-form" data-class-task-form><label>Nosaukums<input name="title" maxlength="120" required></label><div class="organizer-form-grid"><label>Veids<select name="type"><option value="homework">Mājasdarbs</option><option value="test">Pārbaudes darbs</option><option value="project">Projekts</option></select></label><label>Priekšmets<input name="subject" maxlength="80"></label><label>Termiņš<input name="date" type="date" data-riga-today value="#{today}" required></label><label>Prioritāte<select name="priority"><option value="normal">Parasta</option><option value="high">Svarīga</option><option value="low">Kad ir laiks</option></select></label></div><button type="submit">Pievienot termiņu</button></form><div data-class-tasks></div></section></div>
  <section class="organizer-card organizer-week-card"><div class="organizer-heading"><div><span class="eyebrow">NEDĒĻAS SKATS</span><h2 data-class-week-title></h2></div><div class="organizer-focus-controls"><label>Fokuss (min)<input type="number" min="1" max="120" value="25" data-focus-minutes></label><button type="button" data-focus-start>Sākt / pauze</button><button type="button" data-focus-reset>Atiestatīt</button></div></div><div class="class-week-grid" data-class-week></div><div class="focus-status" data-focus-status role="timer" aria-live="off">Taimeris ir apturēts.</div></section><aside class="school-design-callout"><div><span class="eyebrow">TAVS STILS UZ PAPĪRA</span><h2>Izvēlies savu mācību nedēļas dizainu</h2><p>15 oriģināli noformējumi ar skaidru hierarhiju un vietu taviem ierakstiem.</p></div><a class="button" href="#v2-designs">Apskatīt 15 dizainus <span aria-hidden="true">↓</span></a></aside><p class="organizer-status" data-class-status role="status" aria-live="polite"></p><details class="organizer-privacy"><summary>Laika josla, atkārtojumi un dati</summary><p>Plānotājs glabā stundas un termiņus tikai šajā pārlūkā. Stundas tiek atkārtotas izvēlētajā mācību periodā, izmantojot Europe/Riga laika joslu, tādēļ vasaras un ziemas laika maiņas saglabā vietējo pulksteņa laiku. JSON dublējums ir paredzēts pārvietošanai uz citu ierīci. Šeit ievadītie datumi nav oficiāls eksāmenu grafiks.</p></details>
  </section>)
end
